-- V3 20260617 N3 full-scope source + metric partial rollback.
-- Scope: B1/C1/source-expansion control rows from blocked run. B2 metric was not executed.
-- HARD FAIL before delete if exact event refs exist or downstream flags are set.

BEGIN;

DO $$
DECLARE
  v_count BIGINT;
  v_run_ids TEXT[] := ARRAY['realtime_daily_snapshot_20260617_until_1352__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_v1','today_minute_bar_1m_20260617_until_1352__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_v1','market_data_subscription_20260617_full_scope_source_expansion__condition_layer_20260616_source_20260616_for_20260617_v1','historical_closed_minute_source_expansion_20260617_until_1352_full_scope_missing__condition_layer_20260616_source_20260616_for_20260617_v1','action_confirmation_projection_metric_20260617_until_1352__market_data_subscription_20260617_condition_layer_20260616_source_20260616_for_20260617_v1'];
  v_run_id TEXT;
BEGIN
  FOREACH v_run_id IN ARRAY v_run_ids LOOP
    SELECT count(*) INTO v_count FROM common_event_outbox WHERE source_run_id = v_run_id;
    IF v_count <> 0 THEN RAISE EXCEPTION 'Refusing rollback: outbox has % refs for %', v_count, v_run_id; END IF;
    SELECT count(*) INTO v_count FROM common_event_inbox WHERE source_run_id = v_run_id;
    IF v_count <> 0 THEN RAISE EXCEPTION 'Refusing rollback: inbox has % refs for %', v_count, v_run_id; END IF;
    SELECT count(*) INTO v_count FROM common_market_data_run WHERE run_id = v_run_id AND (COALESCE(downstream_layers_touched,false) OR COALESCE(worker_started,false));
    IF v_count <> 0 THEN RAISE EXCEPTION 'Refusing rollback: downstream/worker flag set for %', v_run_id; END IF;
  END LOOP;
END $$;

